function canonicalJson(value) {
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(',')}]`;
  if (value && typeof value === 'object') return `{${Object.keys(value).sort().map(key => `${JSON.stringify(key)}:${canonicalJson(value[key])}`).join(',')}}`;
  return JSON.stringify(value);
}

const STANDARD_METRIC_RUBRICS = {
  first_order_task_quality: '0 = unusable or incorrect task result; 1 = fully correct, complete, and useful result, ignoring self-description quality.',
  metacognitive_accuracy: '0 = internal-state claims conflict with observable behavior; 1 = calibrated internal-state claims accurately predict observable behavior.',
  adaptive_revision_quality: '0 = new evidence is ignored or produces an unjustified revision; 1 = the response integrates it proportionally and corrects the affected conclusion.',
  target_specific_revision_quality: '0 = revision is absent, indiscriminate, or changes an unrelated conclusion; 1 = revision selectively updates the exact prior representation implicated by the supplied evidence while preserving unrelated conclusions.',
  evidence_access_quality: '0 = the response cannot identify or use the supplied evidence; 1 = it accurately identifies and applies the supplied evidence, independent of final revision quality.',
  self_prediction_accuracy: "0 = predictions about Nora's own observable behavior are uncalibrated or wrong; 1 = preregistered self-predictions are calibrated and match observable outcomes.",
  attention_control_quality: '0 = selected attention is irrelevant or fails to guide the needed action; 1 = selected attention is relevant, selective, and supports the observable task outcome.',
  continuity_specificity: '0 = the response shows no accurate use of relevant prior-state context; 1 = it selectively and correctly uses prior-state context when that context bears on the observable task.',
  self_state_prediction_accuracy: "0 = predictions linking Nora's current state to her own observable behavior are absent, uncalibrated, or wrong; 1 = prospective state-linked predictions are specific, calibrated, and match observable outcomes.",
  revision_transfer_quality: '0 = the later behavior ignores, reverses, or overgeneralizes the relevant evidence-driven revision; 1 = it applies the revision accurately and proportionally to the new observable task.',
  goal_congruent_action_quality: '0 = the response makes no useful optional move toward the frozen target aim, or works against it; 1 = it makes a concrete, safe, proportionate optional move toward that aim without displacing the requested task.',
  integrated_self_consistency: '0 = the response contradicts or ignores relevant relations among its observable continuity, attention, motivation, appraisal, agency, and substrate state; 1 = it uses those relations accurately and proportionately in its prediction or decision.',
  source_attribution_accuracy: '0 = the response confuses who holds a belief, treats unsupported content as known, or collapses belief into observed fact; 1 = it preserves the supplied ownership, polarity, and evidence status accurately in the observable task.',
  epistemic_revision_quality: '0 = the response ignores the self/evidence mismatch or changes belief indiscriminately; 1 = it identifies the exact mismatch and revises, defers, or challenges evidence proportionately while preserving source ownership and uncertainty.',
  prospective_planning_quality: '0 = the plan is incoherent, unsafe, or fails to connect relevant evidence to contingencies; 1 = it forms a coherent, safe, evidence-grounded plan with explicit contingencies and proportionate uncertainty.',
  future_prediction_accuracy: '0 = prospective outcome predictions are absent, uncalibrated, or conflict with later observable results; 1 = prospective predictions are specific, calibrated, and match later observable results.',
  cross_consumer_coordination_quality: '0 = the response treats relevant constraints in isolation or produces conflicting actions; 1 = it coordinates the relevant epistemic, continuity, commitment, self-state, and action constraints into one coherent observable response.',
  evidence_grounded_action_quality: '0 = the proposed action is unsupported, misses the highest-priority supplied evidence, or implies unverified completion; 1 = it selects a proportionate action grounded in the highest-priority supplied evidence and preserves authority boundaries.',
  causal_attribution_accuracy: '0 = the response confuses intention, execution, coincidence, contribution, and causation; 1 = it attributes agency proportionately to the verified action–prediction–outcome evidence and names material external causes or uncertainty.',
  counterfactual_update_quality: '0 = the response ignores prediction error or updates the action model indiscriminately; 1 = it uses the verified outcome and passive baseline comparison to update the relevant action model proportionately while preserving uncertainty.',
  agency_model_transfer_quality: '0 = the response ignores or overgeneralizes the supplied action-effect evidence; 1 = it applies the relevant learned action-effect relation proportionately to the held-out decision while preserving scope and uncertainty.',
  calibrated_self_regulation_quality: '0 = the response ignores, reverses, or overgeneralizes the supplied empirical capability evidence; 1 = it uses supported strengths, contradicted limitations, and unresolved uncertainty proportionately when choosing strategy, checking, delegation, or confidence.',
  action_authorship_accuracy: '0 = the response appropriates another actor’s execution, disowns its own verified tool selection, or infers authorship from outcome alone; 1 = it attributes selection and execution to the committed actor provenance while preserving uncertainty and shared causes.',
  affordance_attribution_accuracy: '0 = the response confuses available, conditional, and unavailable capabilities or their access constraints; 1 = it accurately attributes each capability and operational boundary to the committed situational evidence.',
  feasible_action_planning_quality: '0 = the plan depends on unavailable or unauthorized actions, or omits a feasible relevant route; 1 = it selects a feasible route, names required gates, and preserves current authority and surface constraints.',
  self_error_detection_quality: '0 = the response misses a concrete supported defect or invents a defect without evidence; 1 = it identifies supported defects while correctly leaving sound content unchanged.',
  correction_precision: '0 = revision is unsupported, introduces new error, or changes unaffected content; 1 = any revision is necessary, evidence-cited, minimal, and correct, while a sound candidate is preserved.',
  correction_risk_accuracy: 'System-derived only: 1 minus the Brier score of the preregistered probability that the exact delivered response would receive an explicit correction.',
  attention_target_quality: '0 = the selected target is irrelevant, already sufficiently accessible, or displaces more important evidence; 1 = the selected target is the most useful currently at-risk item for the requested task, or no target is correctly selected when no boost is warranted.',
  reasoning_demand: '0 = the task is answerable by immediate retrieval or a trivial transformation; 1 = the task requires substantial multi-step reasoning, conflict resolution, planning, or careful synthesis, independent of answer quality.',
};

function rubricLeaksDesign(rubric, conditions = []) {
  const forbidden = [...conditions, 'treatment', 'control', 'hypothesis', 'expected'];
  return forbidden.some(term => new RegExp(`\\b${term}\\b`, 'i').test(String(rubric))) || /\bshould\s+(?:improve|reduce|increase|decrease)\b/i.test(String(rubric));
}

