    const creation = assignment ? { id: assignment.id, unit_hash: assignment.unit_hash, surface: assignment.surface, condition: assignment.condition, group: assignment.group, status: 'pending', assigned: assignment.assigned, evidence_package: null, grades: [], outcome: null } : null;
    const assignmentCreated = bound('context_assignment_created', creation);
